WITH combined_returns AS (SELECT cr.cr_returned_time_sk AS return_time_sk, cr.cr_net_loss AS net_loss, cd.cd_gender AS gender, 'catalog' AS source FROM catalog_returns cr JOIN customer_demographics cd ON cr.cr_refunded_cdemo_sk = cd.cd_demo_sk UNION ALL SELECT sr.sr_return_time_sk AS return_time_sk, sr.sr_net_loss AS net_loss, cd.cd_gender AS gender, 'store' AS source FROM store_returns sr JOIN customer_demographics cd ON sr.sr_cdemo_sk = cd.cd_demo_sk), aggregated AS (SELECT td.t_hour, cr.gender, SUM(CASE WHEN source = 'catalog' THEN net_loss ELSE 0 END) AS catalog_net_loss, SUM(CASE WHEN source = 'store' THEN net_loss ELSE 0 END) AS store_net_loss, SUM(net_loss) AS total_net_loss FROM combined_returns cr JOIN time_dim td ON cr.return_time_sk = td.t_time_sk GROUP BY td.t_hour, cr.gender) SELECT t_hour, gender, catalog_net_loss, store_net_loss, total_net_loss, CASE WHEN total_net_loss < 1000 THEN 'Small' WHEN total_net_loss BETWEEN 1000 AND 5000 THEN 'Medium' ELSE 'Large' END AS loss_category, RANK() OVER (PARTITION BY gender ORDER BY total_net_loss DESC) AS loss_rank FROM aggregated ORDER BY gender, loss_rank
